function WMa(){this.DDd=this.CDd=null;XMa=this;this.DDd=this.CDd='{\n  "$schema" : "http://json-schema.org/draft-07/schema#",\n  "title" : "LLM Metadata Classifier Schema",\n  "$ref" : "#/definitions/LLMMetadataClassifier",\n  "definitions" : {\n    "LLMMetadataClassifier" : {\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "platform" ],\n      "properties" : {\n        "platform" : {\n          "description" : "The name of the platform for this LLM (e.g., \'Gemini\', \'OpenAI\', \'AzureOpenai\', or any other custom platform name)",\n          "anyOf" : [ {\n            "type" : "string",\n            "enum" : [ "Gemini", "OpenAI", "AzureOpenai" ]\n          }, {\n            "type" : "string"\n          } ]\n        },\n        "name" : {\n          "description" : "A human-readable display name for this LLM platform, distinct from the \'platform\' identifier",\n          "type" : "string"\n        },\n        "inputFormat" : {\n          "description" : "The request/response wire format this LLM platform expects",\n          "type" : "string",\n          "enum" : [ "openai", "anthropic", "gemini" ]\n        },\n        "authentication" : {\n          "description" : "The authentication kinds supported by this LLM platform, along with optional default configuration values. An absent property means the authentication requirements are unknown, whereas a single entry with kind \'none\' means the platform explicitly requires no authentication.",\n          "type" : "array",\n          "items" : {\n            "$ref" : "#/definitions/LLMAuthenticationDefault"\n          }\n        },\n        "models" : {\n          "description" : "An array of model identifiers available on this LLM platform, either as a plain identifier string or as a detailed model object",\n          "type" : "array",\n          "items" : {\n            "anyOf" : [ {\n              "type" : "string",\n              "description" : "A model identifier (e.g., \'gpt-4\', \'gemini-pro\')"\n            }, {\n              "$ref" : "#/definitions/LLMModelDetail"\n            } ]\n          }\n        },\n        "defaultUrl" : {\n          "description" : "Named default URL templates for this LLM platform (e.g. templated with \'{domain}\' placeholders)",\n          "type" : "array",\n          "items" : {\n            "$ref" : "#/definitions/LLMDefaultUrl"\n          }\n        },\n        "kind" : {\n          "description" : "The type of llm-platform (e.g., \'llm-gw\')",\n          "type" : "string"\n        },\n        "capabilities" : {\n          "$ref" : "#/definitions/LLMCapabilities"\n        },\n        "policyRef" : {\n          "description" : "Reference to an adapter policy that adapts the upstream LLM provider\'s language/wire format to the \'inputFormat\' expected by this LLM platform.",\n          "type" : "object",\n          "additionalProperties" : false,\n          "required" : [ "groupId", "assetId" ],\n          "properties" : {\n            "groupId" : {\n              "description" : "The group identifier of the policy",\n              "type" : "string"\n            },\n            "assetId" : {\n              "description" : "The asset identifier of the policy",\n              "type" : "string"\n            },\n            "version" : {\n              "description" : "The version of the policy. If not specified, the latest available version is used.",\n              "type" : "string"\n            }\n          }\n        },\n        "provenance" : {\n          "$ref" : "#/definitions/ProvenanceDefinition"\n        }\n      }\n    },\n    "LLMServer" : {\n      "description" : "The core declaration of an LLM server/platform: identity, supported authentication, and available models. Shared between the LLM Metadata Classifier and agent_network_v2\'s embedded LLM entities.",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "platform" ],\n      "properties" : {\n        "platform" : {\n          "description" : "The name of the platform for this LLM (e.g., \'Gemini\', \'OpenAI\', \'AzureOpenai\', or any other custom platform name)",\n          "anyOf" : [ {\n            "type" : "string",\n            "enum" : [ "Gemini", "OpenAI", "AzureOpenai" ]\n          }, {\n            "type" : "string"\n          } ]\n        },\n        "name" : {\n          "description" : "A human-readable display name for this LLM platform, distinct from the \'platform\' identifier",\n          "type" : "string"\n        },\n        "inputFormat" : {\n          "description" : "The request/response wire format this LLM platform expects",\n          "type" : "string",\n          "enum" : [ "openai", "anthropic", "gemini" ]\n        },\n        "authentication" : {\n          "description" : "The authentication kinds supported by this LLM platform, along with optional default configuration values. An absent property means the authentication requirements are unknown, whereas a single entry with kind \'none\' means the platform explicitly requires no authentication.",\n          "type" : "array",\n          "items" : {\n            "$ref" : "#/definitions/LLMAuthenticationDefault"\n          }\n        },\n        "models" : {\n          "description" : "An array of model identifiers available on this LLM platform, either as a plain identifier string or as a detailed model object",\n          "type" : "array",\n          "items" : {\n            "anyOf" : [ {\n              "type" : "string",\n              "description" : "A model identifier (e.g., \'gpt-4\', \'gemini-pro\')"\n            }, {\n              "$ref" : "#/definitions/LLMModelDetail"\n            } ]\n          }\n        },\n        "defaultUrl" : {\n          "description" : "Named default URL templates for this LLM platform (e.g. templated with \'{domain}\' placeholders)",\n          "type" : "array",\n          "items" : {\n            "$ref" : "#/definitions/LLMDefaultUrl"\n          }\n        },\n        "capabilities" : {\n          "$ref" : "#/definitions/LLMCapabilities"\n        }\n      }\n    },\n    "LLMDefaultUrl" : {\n      "description" : "A named default URL template for this LLM platform",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "name", "url" ],\n      "properties" : {\n        "name" : {\n          "description" : "The name of this default URL entry (e.g. \'default\', \'us-gov\', \'eu\')",\n          "type" : "string"\n        },\n        "url" : {\n          "description" : "The default URL template, which may contain placeholders (e.g. \'https://{domain}.openai.azure.com\')",\n          "type" : "string"\n        }\n      }\n    },\n    "LLMCapabilities" : {\n      "description" : "The set of capabilities supported, shared between an LLM platform and its individual models",\n      "type" : "object",\n      "additionalProperties" : false,\n      "properties" : {\n        "embeddings" : {\n          "description" : "Whether generating embeddings is supported",\n          "type" : "boolean"\n        },\n        "toolCalling" : {\n          "description" : "Whether tool/function calling is supported",\n          "type" : "boolean"\n        },\n        "structuredOutput" : {\n          "description" : "Whether structured output is supported",\n          "type" : "boolean"\n        },\n        "codeExecution" : {\n          "description" : "Whether code execution is supported",\n          "type" : "boolean"\n        },\n        "citations" : {\n          "description" : "Whether citations are supported",\n          "type" : "boolean"\n        },\n        "batchProcessing" : {\n          "description" : "Whether batch processing is supported",\n          "type" : "boolean"\n        },\n        "imageInput" : {\n          "description" : "Whether image input is supported",\n          "type" : "boolean"\n        },\n        "pdfInput" : {\n          "description" : "Whether PDF input is supported",\n          "type" : "boolean"\n        },\n        "structuredOutputs" : {\n          "description" : "Whether structured outputs are supported",\n          "type" : "boolean"\n        },\n        "reasoning" : {\n          "description" : "Reasoning support",\n          "type" : "object",\n          "additionalProperties" : false,\n          "properties" : {\n            "supported" : {\n              "description" : "Whether reasoning is supported",\n              "type" : "boolean"\n            },\n            "type" : {\n              "description" : "The type of reasoning supported (e.g. \'adaptive\')",\n              "type" : "string"\n            },\n            "effortLevels" : {\n              "description" : "The reasoning effort levels supported",\n              "type" : "array",\n              "items" : {\n                "type" : "string"\n              }\n            }\n          }\n        }\n      }\n    },\n    "LLMModelDetail" : {\n      "description" : "Detailed metadata about a single model",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "id" ],\n      "properties" : {\n        "id" : {\n          "description" : "A model identifier (e.g., \'gpt-4\', \'gemini-pro\')",\n          "type" : "string"\n        },\n        "label" : {\n          "description" : "The human-readable label of the model",\n          "type" : "string"\n        },\n        "description" : {\n          "description" : "A human-readable description of the model",\n          "type" : "string"\n        },\n        "limits" : {\n          "description" : "Token and context limits for the model",\n          "type" : "object",\n          "additionalProperties" : false,\n          "properties" : {\n            "maxInputTokens" : {\n              "description" : "The maximum number of input tokens supported",\n              "type" : "integer"\n            },\n            "maxOutputTokens" : {\n              "description" : "The maximum number of output tokens supported",\n              "type" : "integer"\n            },\n            "supportsPromptCaching" : {\n              "description" : "Whether the model supports prompt caching",\n              "type" : "boolean"\n            },\n            "maxCachedTokens" : {\n              "description" : "The maximum number of tokens that can be cached",\n              "type" : "integer"\n            }\n          }\n        },\n        "capabilities" : {\n          "$ref" : "#/definitions/LLMCapabilities"\n        },\n        "pricing" : {\n          "description" : "Pricing information for the model, expressed per million tokens",\n          "type" : "object",\n          "additionalProperties" : false,\n          "properties" : {\n            "inputPerMillion" : {\n              "description" : "The price per million input tokens",\n              "type" : "number"\n            },\n            "outputPerMillion" : {\n              "description" : "The price per million output tokens",\n              "type" : "number"\n            },\n            "cachedInputPerMillion" : {\n              "description" : "The price per million cached input tokens",\n              "type" : "number"\n            },\n            "reasoningPerMillion" : {\n              "description" : "The price per million reasoning tokens",\n              "type" : "number"\n            }\n          }\n        },\n        "lifecycle" : {\n          "description" : "Lifecycle information for the model",\n          "type" : "object",\n          "additionalProperties" : false,\n          "properties" : {\n            "status" : {\n              "description" : "The lifecycle status of the model (e.g. \'active\', \'deprecated\', \'sunset\')",\n              "type" : "string"\n            },\n            "releasedAt" : {\n              "description" : "The date and time the model was released",\n              "type" : "string"\n            },\n            "sunsetAt" : {\n              "description" : "The date and time the model will be or was sunset, if known",\n              "type" : [ "string", "null" ]\n            }\n          }\n        }\n      }\n    },\n    "LLMAuthenticationDefault" : {\n      "description" : "A supported authentication kind for this LLM platform, with optional default configuration values",\n      "anyOf" : [ {\n        "$ref" : "#/definitions/NoAuthDefault"\n      }, {\n        "$ref" : "#/definitions/ApiKeyAuthDefault"\n      }, {\n        "$ref" : "#/definitions/BasicAuthDefault"\n      }, {\n        "$ref" : "#/definitions/ApiKeyClientCredentialsAuthDefault"\n      }, {\n        "$ref" : "#/definitions/OAuth2ClientCredentialsAuthDefault"\n      }, {\n        "$ref" : "#/definitions/JwtBearerAuthDefault"\n      }, {\n        "$ref" : "#/definitions/CustomAuthDefault"\n      }, {\n        "$ref" : "#/definitions/AmazonSigV4AuthDefault"\n      } ]\n    },\n    "NoAuthDefault" : {\n      "description" : "Indicates the LLM platform explicitly requires no authentication. When used, \'none\' should be the only entry in the authentication array.",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'none\'",\n          "const" : "none",\n          "type" : "string"\n        }\n      }\n    },\n    "ApiKeyAuthDefault" : {\n      "description" : "Default configuration for the \'apiKey\' authentication kind",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'apiKey\'",\n          "const" : "apiKey",\n          "type" : "string"\n        },\n        "defaultConfiguration" : {\n          "type" : "object",\n          "additionalProperties" : false,\n          "description" : "Optional default values for API Key authentication",\n          "required" : [ "headerName" ],\n          "properties" : {\n            "headerName" : {\n              "description" : "The name of the header to be used.",\n              "type" : "string"\n            },\n            "apiKey" : {\n              "description" : "The default value of the apiKey",\n              "type" : "string"\n            },\n            "apiKeyPrefix" : {\n              "description" : "The prefix to prepend to the API key value, for example \'Bearer\'",\n              "type" : "string"\n            },\n            "headersToRemove" : {\n              "description" : "The list of header names to remove from the request",\n              "type" : "array",\n              "items" : {\n                "type" : "string"\n              }\n            },\n            "additionalHeaders" : {\n              "title" : "Additional Headers",\n              "description" : "Extra headers injected into the outbound request after the API key is injected. Each entry names a header and supplies either a static value or a DataWeave valueExpression (the expression wins when it resolves to a non-empty string, otherwise the static value is used). An entry whose effective value is empty is skipped with a warning. Each header is set with replace semantics \u2014 any pre-existing instance is removed first.",\n              "type" : "array",\n              "default" : [ ],\n              "items" : {\n                "type" : "object",\n                "additionalProperties" : false,\n                "required" : [ "key" ],\n                "properties" : {\n                  "key" : {\n                    "title" : "Header Name",\n                    "description" : "The name of the header to inject, e.g. x-request-source or anthropic-version.",\n                    "type" : "string"\n                  },\n                  "value" : {\n                    "title" : "Header Value",\n                    "description" : "Static value for the header. Used when valueExpression is unset or resolves empty. Provide either value or valueExpression.",\n                    "type" : "string"\n                  },\n                  "valueExpression" : {\n                    "title" : "Header Value Expression",\n                    "description" : "DataWeave expression resolving the header value at request time from request headers, stream properties, or the request body, e.g. \\"#[attributes.headers[\'x-source\']]\\" or \\"#[payload.metadata.tenant]\\". Takes precedence over value only when it resolves to a non-empty string. The request body is buffered only when the expression actually references payload.",\n                    "type" : "string",\n                    "format" : "dataweave",\n                    "bindings" : {\n                      "attributes" : true,\n                      "payload" : {\n                        "mimeType" : "json"\n                      }\n                    }\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "BasicAuthDefault" : {\n      "description" : "Default configuration for the \'basic\' authentication kind",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'basic\'",\n          "const" : "basic",\n          "type" : "string"\n        },\n        "defaultConfiguration" : {\n          "type" : "object",\n          "additionalProperties" : false,\n          "description" : "Optional default values for Basic authentication",\n          "properties" : {\n            "username" : {\n              "description" : "The default username for authentication",\n              "type" : "string"\n            },\n            "password" : {\n              "description" : "The default password for authentication",\n              "type" : "string"\n            },\n            "headerName" : {\n              "description" : "The name of the header where to set the key. If not specified \'Authorization\' is set by default",\n              "type" : "string"\n            }\n          }\n        }\n      }\n    },\n    "ApiKeyClientCredentialsAuthDefault" : {\n      "description" : "Default configuration for the \'apikey-client-credentials\' authentication kind",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'apikey-client-credentials\'",\n          "const" : "apikey-client-credentials",\n          "type" : "string"\n        },\n        "defaultConfiguration" : {\n          "type" : "object",\n          "additionalProperties" : false,\n          "description" : "Optional default values for API Key Client Credentials authentication",\n          "properties" : {\n            "clientId" : {\n              "type" : "object",\n              "description" : "Default values for the client ID",\n              "additionalProperties" : false,\n              "properties" : {\n                "value" : {\n                  "type" : "string",\n                  "description" : "The default value for the clientId"\n                },\n                "name" : {\n                  "type" : "string",\n                  "description" : "The name for the clientId, by default \'client_id\'"\n                }\n              }\n            },\n            "clientSecret" : {\n              "type" : "object",\n              "description" : "Default values for the client secret",\n              "additionalProperties" : false,\n              "properties" : {\n                "value" : {\n                  "type" : "string",\n                  "description" : "The default value for the clientSecret"\n                },\n                "name" : {\n                  "type" : "string",\n                  "description" : "The name for the clientSecret, by default \'client_secret\'"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "OAuth2ClientCredentialsAuthDefault" : {\n      "description" : "Default configuration for the \'oauth2-client-credentials\' authentication kind",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'oauth2-client-credentials\'",\n          "const" : "oauth2-client-credentials",\n          "type" : "string"\n        },\n        "defaultConfiguration" : {\n          "type" : "object",\n          "additionalProperties" : false,\n          "description" : "Optional default values for OAuth 2.0 Client Credentials authentication",\n          "properties" : {\n            "clientId" : {\n              "type" : "string",\n              "description" : "The default client ID"\n            },\n            "clientSecret" : {\n              "type" : "string",\n              "description" : "The default client secret"\n            },\n            "token" : {\n              "type" : "object",\n              "additionalProperties" : false,\n              "description" : "Default configuration on how to fetch the token",\n              "properties" : {\n                "url" : {\n                  "type" : "string",\n                  "description" : "The default url of the token provider"\n                },\n                "timeout" : {\n                  "type" : "number",\n                  "description" : "Default time in seconds to wait for the service to return the token"\n                },\n                "bodyEncoding" : {\n                  "type" : "string",\n                  "description" : "Default content encoding for the request body. Must be \'form\' (application/x-www-form-urlencoded) or \'json\' (application/json)",\n                  "enum" : [ "form", "json" ]\n                }\n              }\n            },\n            "scopes" : {\n              "type" : "array",\n              "items" : {\n                "type" : "string"\n              },\n              "description" : "Default array of scopes to request"\n            }\n          }\n        }\n      }\n    },\n    "JwtBearerAuthDefault" : {\n      "description" : "Default configuration for the \'oauth2-jwt-bearer\' authentication kind. The gateway obtains an OAuth 2.0 access token using an RS256-signed JWT (RFC 7523) and injects it as a Bearer token on the outbound request",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'oauth2-jwt-bearer\'",\n          "const" : "oauth2-jwt-bearer",\n          "type" : "string"\n        },\n        "defaultConfiguration" : {\n          "type" : "object",\n          "additionalProperties" : false,\n          "description" : "Optional default values for JWT Bearer authentication",\n          "properties" : {\n            "mode" : {\n              "description" : "Which RFC 7523 use the JWT serves. \'authorization-grant\' (section 2.1) sends the JWT as the grant. \'client-authentication\' (section 2.2) sends it as a client assertion on a client_credentials grant (private_key_jwt). Defaults to \'authorization-grant\'",\n              "type" : "string",\n              "enum" : [ "authorization-grant", "client-authentication" ]\n            },\n            "signingKey" : {\n              "description" : "The default RSA private key in PKCS#8 PEM format (BEGIN PRIVATE KEY) used to sign the JWT with RS256. The modulus must be at least 2048 bits. Should be supplied through a secret or property reference",\n              "type" : "string"\n            },\n            "clientId" : {\n              "description" : "The default OAuth client identifier, sent as the client_id form parameter when set. Only applicable in \'authorization-grant\' mode; in \'client-authentication\' the issuer is the client identifier and a configured value must equal the issuer",\n              "type" : "string"\n            },\n            "issuer" : {\n              "description" : "The default value of the JWT \'iss\' claim. In \'client-authentication\' mode it must be the OAuth client_id",\n              "type" : "string"\n            },\n            "subject" : {\n              "description" : "The default value of the JWT \'sub\' claim. Defaults to the issuer. In \'authorization-grant\' mode, set it to the principal the token is requested for (for example a Salesforce username); Google documents \'sub\' as optional and reserved for domain-wide delegation, so leave it unset unless delegated access is needed. In \'client-authentication\' mode it must be unset or equal to the issuer",\n              "type" : "string"\n            },\n            "audience" : {\n              "description" : "The default value of the JWT \'aud\' claim, identifying the authorization server. Most servers expect the token endpoint URL",\n              "type" : "string"\n            },\n            "keyId" : {\n              "description" : "The default value of the JWT header \'kid\', for servers that select the verification key by id",\n              "type" : "string"\n            },\n            "tokenEndpoint" : {\n              "description" : "The default full URL of the token endpoint, for example https://idp.example.com/oauth2/token. The scheme, host and port identify the upstream service; the token request is POSTed to the path of this URL, used as configured",\n              "type" : "string"\n            },\n            "scope" : {\n              "description" : "The default OAuth scope; separate several scopes with spaces. Where it is sent is set by \'scopePlacement\'. Nothing is sent when unset",\n              "type" : "string"\n            },\n            "scopePlacement" : {\n              "description" : "Where the scope is sent. \'parameter\' sends it as the scope form parameter, \'claim\' sends it as a scope claim inside the JWT, and \'both\' sends it in both places. Only \'parameter\' is valid in \'client-authentication\' mode. Defaults to \'parameter\'",\n              "type" : "string",\n              "enum" : [ "parameter", "claim", "both" ]\n            },\n            "assertionLifetime" : {\n              "description" : "Default lifetime of the JWT (exp - iat) in seconds. Must be greater than 0. Defaults to 300",\n              "type" : "integer",\n              "exclusiveMinimum" : 0\n            },\n            "defaultTokenLifetime" : {\n              "description" : "Default lifetime in seconds assumed for an access token whose response has no expires_in. When expires_in is present it always wins. Defaults to 300",\n              "type" : "integer"\n            },\n            "timeout" : {\n              "description" : "Default bound on the token endpoint round trip, in milliseconds. It applies only when a token is minted; a cache hit makes no network call. Defaults to 10000",\n              "type" : "integer"\n            },\n            "headersToRemove" : {\n              "description" : "Additional header names stripped from the outbound request before the token is injected, e.g. to remove a client-supplied credential sent under a different header. The Authorization header is always removed regardless of this list",\n              "type" : "array",\n              "items" : {\n                "type" : "string"\n              }\n            },\n            "additionalHeaders" : {\n              "description" : "Extra headers injected into the outbound request after the Authorization header, for upstreams that expect literal headers besides the token. Each header is set with replace semantics: any pre-existing instance is removed first. An entry with an empty value is skipped",\n              "type" : "array",\n              "items" : {\n                "type" : "object",\n                "additionalProperties" : false,\n                "required" : [ "key", "value" ],\n                "properties" : {\n                  "key" : {\n                    "description" : "The name of the header to inject, e.g. x-request-source",\n                    "type" : "string"\n                  },\n                  "value" : {\n                    "description" : "Static value of the header",\n                    "type" : "string"\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "CustomAuthDefault" : {\n      "description" : "Default configuration for a custom authentication kind implemented via a referenced policy",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind", "policy" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'custom\'",\n          "const" : "custom",\n          "type" : "string"\n        },\n        "policy" : {\n          "type" : "object",\n          "additionalProperties" : false,\n          "description" : "The policy that implements this custom authentication kind",\n          "required" : [ "ref" ],\n          "properties" : {\n            "ref" : {\n              "$ref" : "#/definitions/PolicyBindingRef"\n            }\n          }\n        },\n        "defaultConfiguration" : {\n          "type" : "object",\n          "additionalProperties" : true,\n          "description" : "Optional default values for the referenced policy\'s configuration"\n        }\n      }\n    },\n    "AmazonSigV4AuthDefault" : {\n      "description" : "Configuration for the \'amazonSigv4\' authentication kind. This kind has no default configuration values",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "kind" ],\n      "properties" : {\n        "kind" : {\n          "description" : "The authentication type - must be \'amazonSigv4\'",\n          "const" : "amazonSigv4",\n          "type" : "string"\n        }\n      }\n    },\n    "ProvenanceDefinition" : {\n      "description" : "The provenance object used in all metadata files.",\n      "additionalProperties" : false,\n      "type" : "object",\n      "properties" : {\n        "id" : {\n          "description" : "A urn that identifies the original resource that generated this metadata.",\n          "type" : "string",\n          "format" : "uri"\n        },\n        "createdAt" : {\n          "description" : "The timestamp where the original resource was created",\n          "type" : "string",\n          "format" : "date-time"\n        },\n        "updatedAt" : {\n          "description" : "The timestamp where the original resource was updated",\n          "type" : "string",\n          "format" : "date-time"\n        },\n        "version" : {\n          "description" : "The version in the target system of this resource",\n          "type" : "string"\n        },\n        "status" : {\n          "description" : "The status of the resource in the origin system.",\n          "type" : "string"\n        },\n        "url" : {\n          "description" : "The url of the original resource.",\n          "type" : "string"\n        }\n      }\n    },\n    "PolicyBindingRef" : {\n      "@context" : {\n        "@type" : [ "http://anypoint.com/vocabs/agents#Reference", "http://anypoint.com/vocabs/agents/reference/kind#policybinding" ],\n        "@base" : "http://anypoint.com/vocabs/agents#"\n      },\n      "description" : "The reference to a declared policy binding",\n      "type" : "object",\n      "additionalProperties" : false,\n      "required" : [ "name" ],\n      "properties" : {\n        "name" : {\n          "description" : "The name of the policy binding to reference",\n          "type" : "string"\n        },\n        "namespace" : {\n          "description" : "Optional namespace to scope the policy reference",\n          "type" : "string"\n        }\n      }\n    }\n  }\n}'}
